  'Un compte ZENKUU sert à retrouver votre liste de suivi d’un appareil à l’autre. Le site n’exécute aucun ordre et ne détient aucun fonds.': 'ZENKUU のアカウントは、ウォッチリストを端末間で引き継ぐためのものです。当サイトは注文を執行せず、資金も預かりません。',
  'À propos de ZENKUU': 'ZENKUU について',
  'D’abord comprendre. Ensuite décider.': 'まず理解する。決めるのはその後。',
  'Les cotations, les classements et les listes de suivi de ZENKUU s’utilisent sans compte. Celui-ci ne sert qu’à les emporter d’un appareil à l’autre.': 'ZENKUU の相場・ランキング・ウォッチリストはアカウントなしで使えます。アカウントは、それらを端末間で持ち運ぶためだけのものです。',
  'Créer un compte': 'アカウントを作成',
