  /* ── Titres et chapeaux de page ─────────────────────────────────────────── */
  "Données de trading": "取引データ",
  "L’activité du marché crypto en quatre plans : les agrégats mondiaux, la répartition du volume entre les places, l’exposition sur les produits dérivés, puis les mouvements de la période.": "暗号資産市場の動きを四つの角度から。市場全体の集計、取引所ごとの出来高配分、デリバティブの建玉、そして期間中の値動きです。",
  "Points marquants": "注目点",
  "Ce qui sort de l’ordinaire aujourd’hui : ce qu’on regarde, ce qui bouge, ce qui s’échange, ce qui apparaît.": "きょう目立つ動き。何が見られ、何が動き、何が取引され、何が新たに現れたか。",
  "Comment les chiffres affichés sur ZENKUU sont collectés, vérifiés et présentés — et ce qu’ils ne disent pas.": "ZENKUU に表示される数値をどう集め、どう検証し、どう見せているか。そして、その数値が語らないこと。",
  "Classements crypto": "暗号資産ランキング",
  "Quatre palmarès à confronter : ce qui monte, ce qui baisse, ce qui s’échange le plus, et ce qui tourne le plus vite au regard de sa taille.": "見比べるための四つのランキング。上げているもの、下げているもの、最も取引されているもの、そして規模のわりに最も回転が速いもの。",
  "Deux à six actifs côte à côte, toutes classes confondues : trajectoires ramenées à une base commune, puis les chiffres qui les séparent.": "資産クラスを問わず 2〜6 銘柄を並べて比較。共通の基準に揃えた推移と、それらを分ける数値を示します。",
  "Carte thermique du marché": "市場ヒートマップ",
  "Le marché en un coup d’œil : la surface porte la capitalisation, la couleur porte la variation. Basculez entre les pièces et les secteurs, et cliquez un rectangle pour l’ouvrir.": "市場をひと目で。面積が時価総額、色が変動率を表します。銘柄とセクターを切り替え、長方形をクリックすると開きます。",
  "Dérivés": "デリバティブ",
  "Les contrats les plus actifs, leur intérêt ouvert et leur taux de financement. Un contrat perpétuel n’a pas d’échéance : son taux de financement est ce qui le raccroche au cours au comptant.": "最も活発な限月と、その建玉および資金調達率。無期限契約に満期はなく、現物価格につなぎ留めているのが資金調達率です。",
  "Les trois cents actifs dont la source a relevé un cours pour la première fois le plus récemment, du plus récent au plus ancien. Ceux que nous suivons par ailleurs portent leur logo et mènent à leur fiche.": "データ元が最も新しく初値を記録した 300 銘柄を、新しい順に。当サイトでも追跡している銘柄はロゴ付きで、個別ページに移動できます。",
  "Paramètres": "設定",
  "Vos réglages d’affichage, votre compte et l’origine des chiffres. ZENKUU n’exécute aucun ordre et ne détient aucun fonds : il n’y a ici ni moyen de paiement, ni limite de transaction, ni vérification d’identité — et rien à payer, le site n’ayant pas d’offre payante.": "表示の設定、アカウント、そして数値の出どころ。ZENKUU は注文を執行せず、資産も預かりません。決済手段も取引上限も本人確認もなく、有料プランがないため支払うものもありません。",
  "Les places de contrats perpétuels, classées par l’exposition qu’elles portent réellement — l’intérêt ouvert — et non par le volume qu’elles affichent. ZENKUU ne référence aucun carnet d’ordres et ne permet aucune transaction : ce registre situe l’activité, il n’y donne pas accès.": "無期限契約を扱う取引所を、公表出来高ではなく実際に抱える建玉で並べています。ZENKUU は板情報を掲載せず、取引もできません。この一覧は活動の所在を示すだけで、そこへの接続は提供しません。",
  "Où s’échange le marché au comptant": "現物市場が取引される場所",
  "Les places d’échange classées par note de confiance, avec le volume qu’elles déclarent sur 24 heures et la part qu’il représente dans ce classement. ZENKUU ne référence aucun carnet d’ordres et ne permet aucune transaction : ce registre situe l’activité, il n’y donne pas accès.": "取引所を信頼スコア順に並べ、24 時間の申告出来高とこの一覧に占める比率を示します。ZENKUU は板情報を掲載せず、取引もできません。この一覧は活動の所在を示すだけで、そこへの接続は提供しません。",
  "Tableau de bord": "ダッシュボード",
  "Vos actifs suivis et vos préférences d’affichage. ZENKUU n’exécute aucun ordre et ne détient aucun fonds : il n’y a donc ici ni solde, ni portefeuille, ni performance — seulement ce que vous avez choisi de suivre.": "追跡中の銘柄と表示の設定。ZENKUU は注文を執行せず、資産も預かりません。残高もポートフォリオも損益も表示されず、あるのは自分で選んだ銘柄だけです。",

