  /* ── Interface : réglages, contrats, méthode ─────── */
  'Ce que ZENKUU ne fait pas.': 'ZENKUU が行わないこと。',
  'Ce que ZENKUU n’est pas': 'ZENKUU ではないもの',
  'Ce que ZENKUU sait de vous tient en deux lignes : une adresse et un pseudonyme. Il n’y a ni mot de passe, ni profil, ni identité vérifiée.': 'ZENKUU があなたについて把握しているのは二行だけです。アドレスと表示名。パスワードもプロフィールも本人確認もありません。',
  'Ce que cet onglet examine': 'このタブが扱う範囲',
  'Ce que nous ne faisons pas': '私たちが行わないこと',
  'Ce que nous ne reprenons pas de nos sources': '情報源から取り込まないもの',
  'Ce que nous n’affichons pas': '表示しないもの',
  'Ce que vous avez déjà suivi ou surveillé depuis ce navigateur rejoindra votre compte.': 'このブラウザーで既に追跡・監視している内容は、アカウントに引き継がれます。',
  'Ce qui s’est passé': '何が起きたか',
  'Ce qui vient d’apparaître': '登場したばかりのもの',
  'Ce qu’on y trouvera': 'そこにあるもの',
  'Ce seuil est déjà franchi : l’alerte partira au prochain relevé, dans quelques minutes.': 'このしきい値はすでに超えています。アラートは数分後、次の計測時に送信されます。',
  'Certaines lignes disparaissent quand la comparaison mêle plusieurs classes — volume, rang, offre. Ce n’est pas une donnée manquante mais une grandeur qui change de définition : le volume d’une place boursière se compte en titres échangés, celui d’un agrégateur crypto en monnaie. Les aligner donnerait un rapport sans signification.': '資産クラスをまたぐ比較では、出来高・順位・供給量といった行が消えます。データの欠落ではなく、定義そのものが変わるためです。証券取引所は出来高を株数で数え、暗号資産の集計サイトは金額で数えます。並べれば意味のない比率になります。',
  'Ces réglages sont enregistrés dans ce navigateur, sur cet appareil.': 'これらの設定は、この端末のこのブラウザーに保存されます。',
  'Ces sources se demandent par tranches et limitent les appels gratuits : le premier chargement peut prendre quelques secondes. Les suivants sont servis depuis le cache.': 'これらの情報源は分割して問い合わせる必要があり、無料の呼び出し回数にも上限があります。初回の読み込みには数秒かかることがあり、二回目以降はキャッシュから配信されます。',
  'Ces trois réglages ne sont pas rattachés à votre compte : ils ne suivent donc pas d’un appareil à l’autre. Seule votre liste de suivi est synchronisée.': 'この三つの設定はアカウントに紐づかないため、端末をまたいで引き継がれません。同期されるのはウォッチリストだけです。',
  'Cette source se demande une entrée à la fois et limite fortement les appels gratuits : le premier chargement peut prendre plusieurs dizaines de secondes. Les suivants sont servis depuis le cache pendant une heure.': 'この情報源は一件ずつしか問い合わせられず、無料の呼び出し回数も厳しく制限されています。初回の読み込みには数十秒かかることがあり、以後一時間はキャッシュから配信されます。',
