  'Les actifs que vous suivez. Les cours ne sont pas repris ici : ils vivent sur les fiches, où ils sont toujours à jour.': 'あなたが追跡している銘柄です。価格はここには載せません。常に最新である各銘柄ページにあります。',
  'Les alertes de prix préviennent par courriel. Tant que le service d’envoi n’est pas configuré sur cette instance, elles ne sont pas proposées — plutôt que d’être enregistrées sans jamais partir.': '価格アラートはメールで通知します。この環境で送信サービスが未設定のあいだは、保存だけされて届かない状態を避けるため、そもそも提供しません。',
  'Les alertes sont conservées en base. Tant qu’aucune n’est configurée sur cette instance, elles ne peuvent pas être enregistrées.': 'アラートはデータベースに保存されます。この環境で何も設定されていないあいだは保存できません。',
