  'Ouvrez la fiche d’un actif et utilisez le bouton « Suivre » pour l’ajouter ici.': '銘柄ページを開き、「フォロー」ボタンでここに追加してください。',
  'Ouvrez la fiche d’un actif et utilisez le bouton « Suivre » pour l’ajouter ici. Aucun compte n’est nécessaire.': '銘柄ページを開き、「フォロー」ボタンでここに追加してください。アカウントは不要です。',
  'Ouvrez la fiche d’un actif et utilisez « Créer une alerte » pour être prévenu par courriel au franchissement d’un seuil. Aucun compte n’est nécessaire.': '銘柄ページを開き、「アラートを作成」でしきい値超過時のメール通知を設定できます。アカウントは不要です。',
  'Le nombre d’adresses distinctes est plus difficile à gonfler que celui des transactions : combien de mains, et non combien de gestes.': '取引件数より、異なるアドレス数のほうが水増しは困難です。何回動かしたかではなく、何人が持っているか。',
  'La liste de suivi est conservée en base, et c’est elle que cette page réunit. Vos préférences d’affichage, elles, restent enregistrées sur cet appareil.': 'ウォッチリストはデータベースに保存され、このページがそれをまとめます。表示の設定のほうは、この端末に保存されたままです。',
  'La note de confiance est un jugement publié par la source sur la qualité de la liquidité déclarée — pas une mesure, et pas un avis de ZENKUU. Les volumes sont ceux annoncés par les places elles-mêmes.': '信頼スコアは、申告された流動性の質について情報源が公表する判断であり、測定値でも ZENKUU の見解でもありません。出来高は各取引所の自己申告です。',
  'Les autres pools du même jeton de base, du plus profond au moins profond.': '同じベーストークンの他のプール。流動性の厚い順。',
  'Les indicateurs affichés décrivent des données passées. Aucun n’est assorti d’un signal d’achat ou de vente.': '表示している指標は過去のデータを記述するものです。売買シグナルは一切付いていません。',
  'Les langues traduites changent l’interface ; les autres enregistrent votre préférence en attendant leur traduction. Le sélecteur signale lesquelles le sont.': '翻訳済みの言語は表示を切り替えます。それ以外は翻訳が届くまで設定だけを記憶します。どちらかは選択リストに表示されます。',
  'Les listes de suivi sont conservées en base. Tant qu’aucune n’est configurée sur cette instance, elles ne peuvent pas l’être.': 'ウォッチリストはデータベースに保存されます。この環境で何も設定されていないあいだは保存できません。',
  'Message repris dans le courriel — « sortir la moitié », « vérifier le volume »…': 'メールに転記されるメモ。「半分を利確」「出来高を確認」など。',
  'Les cours sont convertis depuis leur devise de cotation au taux de référence BCE, dont la date est rappelée sous chaque montant. Une conversion n’est pas un cours coté.': '価格は建値通貨から ECB の参考レートで換算しており、そのレートの日付を各金額の下に示します。換算値は建値ではありません。',
  'Les cours sont relevés toutes les quinze minutes. Au franchissement du seuil, un courriel part sur l’adresse indiquée à la création. Une alerte ordinaire se désarme alors ; une alerte « à chaque fois » reste armée, avec au plus un envoi par jour.': '価格は 15 分ごとに取得します。しきい値を超えると、作成時に指定したアドレスへメールが届きます。通常のアラートはそこで解除され、「毎回」のアラートは有効なまま、送信は 1 日 1 回までです。',

