  'Un ETF **européen n’y figure pas** — la sélection est américaine.': '**欧州の ETF はここに載りません**。対象は米国のものです。',
  'Un narratif en tête explique souvent la présence d’une demi-douzaine de jetons dans les palmarès ci-dessus.': '上のランキングに半ダースほどの銘柄が並ぶ理由は、その時々の主導的なテーマにあることがよくあります。',
  'Un site de cotation s’arrête à 24 h ; sur la chaîne, cinq minutes comptent.': '価格サイトは 24 時間で止まりますが、チェーン上では 5 分が意味を持ちます。',
  'Une session dure soixante jours. « Tout fermer » révoque celles de tous vos appareils, y compris celui-ci — le geste à faire après avoir utilisé un poste partagé.': 'セッションは 60 日間有効です。「すべて終了」は、この端末を含むすべての端末のセッションを失効させます。共用のパソコンを使ったあとに行う操作です。',
  'Valeur au plus': '上限値',
  'Valorisation diluée': '希薄化後評価額',
  'Valorisation et rentabilité': 'バリュエーションと収益性',
  'Variation par fenêtre': '期間ごとの変動',
  'Voir la liste complète': '全件を見る',
  'Voir toutes les cotations': 'すべての上場を見る',
  'Volatilité annualisée': '年率ボラティリティ',
  'Volume 24 h rapporté à la capitalisation, au-dessus de 50 M$': '24 時間出来高の時価総額比（5,000 万ドル超）',
  'Volume 24 h rapporté à l’intérêt ouvert': '24 時間出来高の建玉比',
  'Volume par devise de cotation': '建値通貨別の出来高',
