  'au cours du jour': '当日レート換算',
  'avec date de règlement': '決済日あり',
  'couples cotés': '取扱ペア',
  'de la sélection, pas du marché NFT': 'この選定範囲であり、NFT 市場全体ではありません',
  'en bitcoin, unité de la source': 'ビットコイン建て（情報源の単位）',
  'par différence, non déclaré comme tel': '差分による算出であり、そう申告されたものではありません',
  'positions non dénouées': '未決済のポジション',
