  'Note de 1 à 10 publiée par la source — ce n’est pas notre évaluation.': '情報源が公表する 1 〜 10 のスコアであり、当サイトの評価ではありません。',
  'Note d’au moins 8 sur 10': '10 点満点で 8 点以上',
