  'Part émise': '発行済み比率',
  'Performance annualisée sur trois ans, calculée sur la valeur liquidative': '3 年間の年率リターン。基準価額をもとに算出しています。',
  'Peu chères': '割安',
  'Places centralisées': '中央集権型取引所',
  'Places décentralisées': '分散型取引所',
  'Plus de mille transactions sur 24 h': '24 時間で 1,000 件超の取引',
  'Plus récents': '新着順',
  'Publié en BITCOIN par la source. Le convertir supposerait de choisir un cours et un instant.': '情報源はこれをビットコイン建てで公表しています。換算するには、どの価格をどの時点で採るかを決める必要が生じます。',
  'Quand une source ne publie pas une information, elle apparaît comme indisponible. Aucune estimation, aucune valeur de remplissage. La règle est portée par la structure du code, pas laissée à la vigilance de qui l’écrit.': '情報源が公表していない項目は、「利用できません」と表示します。推定も、埋め合わせの値もありません。この規則はコードの構造が担保しており、書き手の注意力に委ねてはいません。',
  'Qui échange, et dans quel sens': '誰が、どちら向きに取引しているか',
  'Rafraîchi toutes les 5 minutes. Les secteurs et les places, plus lents, toutes les 30 minutes à 1 heure.': '5 分ごとに更新します。動きの遅いセクターと取引所は、30 分〜1 時間ごとです。',
  'Rang de confiance': '信頼度の順位',
  'Recherche universelle sur les actifs. Alimente l’overlay de l’en-tête ; renvoie identité et rang, sans cours.': '銘柄の横断検索です。ヘッダーのオーバーレイに供給し、価格を含まない識別情報と順位を返します。',
  'Rendement affiché': '表示利回り',
