  'Seule source gratuite de cette donnée. Elle alimente la page des nouvelles cotations.': 'このデータで唯一の無料情報源です。新規上場ページに供給しています。',
  'Séance positive': '上昇して引けた日',
  'Série de prix d’un actif sur la fenêtre demandée. Inclut le volume quand la source le publie dans la même réponse.': '指定した期間における銘柄の価格系列です。情報源が同じ応答に含めている場合は出来高も返します。',
  'Toutes les classes d’actifs, une seule grille de lecture': 'すべての資産クラスを、ひとつの読み方で',
