  /* ── Graphiques, aide et réglages — deuxième lot ─────────────────────────────────────────── */
  'Affichage': 'レイアウト',
  'Apparence': '外観',
  'Aucune source gratuite ne publie l’historique de dominance : nous l’enregistrons à chaque lecture des statistiques globales. La courbe apparaîtra dès que suffisamment de points auront été relevés.': 'ドミナンスの履歴を公開している無料ソースはないため、グローバル統計を読み込むたびに当サイトが自ら記録しています。十分な点が集まり次第、曲線が表示されます。',
  'Capitalisation de Bitcoin': 'ビットコインの時価総額',
  'Capitalisation du panier suivi': '追跡バスケットの時価総額',
  'Capitalisation d’Ethereum': 'イーサリアムの時価総額',
  'Carte indisponible': 'マップを表示できません',
  'Choisir la devise': '通貨を選ぶ',
  'Choisir la langue': '言語を選ぶ',
  'Collections indisponibles': 'コレクションを表示できません',
  'Compte': 'アカウント',
  'Courbes longues indisponibles': '長期チャートを表示できません',
  'Devise': '通貨',
  'Découpage': '区分',
  'Efface le compte, la liste de suivi et les écrans enregistrés. Immédiat et sans période de grâce : conserver trente jours des données que personne ne réclame serait moins protecteur, pas plus.': 'アカウント、ウォッチリスト、保存した画面を削除します。猶予期間なしで即時に行われます。誰も求めていないデータを三十日間保持することは、保護を強めるどころか弱めるからです。',
  'La capitalisation des cryptomonnaies suivies s’élève aujourd’hui à {cap}, en variation de {change} sur vingt-quatre heures, pour un volume échangé de {volume}. Bitcoin en représente {btc}, Ethereum {eth}. Le site suit {count} cryptomonnaies.': '追跡中の暗号資産の時価総額は本日 {cap}、二十四時間の変化率は {change}、取引高は {volume} です。うちビットコインが {btc}、イーサリアムが {eth} を占めます。当サイトは {count} 銘柄を追跡しています。',
  'La dominance ci-dessus est la vraie : Bitcoin rapporté au marché entier, tel que la source le publie. Sa profondeur est celle de nos propres relevés, c’est-à-dire quelques heures. Pour voir la tendance sur douze mois, il faut accepter une mesure approchante — la part de Bitcoin dans un panier de neuf actifs, dont la composition est listée sous les courbes. Elle est tracée dans le cadre « Part de Bitcoin dans le panier », juste en dessous.': '上のドミナンスは本物です。ソースが公開するとおり、市場全体に対するビットコインの比率です。その期間は当サイト自身の記録の長さ、つまり数時間にとどまります。十二か月の傾向を見るには近似値を受け入れる必要があります — 曲線の下に構成を掲げた九銘柄バスケットにおけるビットコインの比率です。すぐ下の「バスケット内のビットコイン比率」の枠に描かれています。',
  'La somme de neuf grandes capitalisations, additionnées jour par jour — pas le marché entier.': '九つの大型時価総額を日ごとに合算したもので、市場全体ではありません。',
  'La source ne publie pas la variation de Bitcoin sur trente jours pour le moment. L’indice compte les actifs qui font mieux que lui : sans cette valeur, il n’a pas de point de comparaison.': '現在、ソースはビットコインの三十日変化率を公開していません。この指数はビットコインを上回る銘柄を数えるため、その値がないと比較の基準を持てません。',
  'Langue': '言語',
  'Le compte, la liste de suivi et les écrans enregistrés seront effacés immédiatement. Cette action est irréversible.': 'アカウント、ウォッチリスト、保存した画面は直ちに削除されます。この操作は取り消せません。',
  'Le panier est figé : il ne suit pas les entrées et sorties du classement. Sa courbe décrit ces neuf actifs, et rien d’autre.': 'バスケットは固定です。ランキングへの出入りには追随しません。その曲線が示すのはこの九銘柄だけです。',
  'Le volume échangé sur l’ensemble des places, tel que la source l’agrège.': 'ソースが集計したかたちでの、全取引所を通じた売買高です。',
  'Même relevé, même profondeur.': '同じ記録、同じ期間です。',
