  'La barre de navigation et la fiche se bornent à 1 680 px et se centrent, à la manière de CoinGecko. C’est l’affichage par défaut.': 'ナビゲーションバーと銘柄ページを 1 680 px までに抑え、中央に寄せます。CoinGecko と同じ方式で、これが既定のレイアウトです。',
  'La barre de navigation et la fiche occupent toute la largeur de l’écran, à la manière de CoinMarketCap. Les autres pages ne changent pas.': 'ナビゲーションバーと銘柄ページが画面幅いっぱいに広がります。CoinMarketCap と同じ方式で、ほかのページは変わりません。',
