  'La part des cent premières capitalisations qui a fait mieux que Bitcoin sur trente jours. Au-dessus de 75 %, le marché favorise les altcoins ; en dessous de 25 %, il se replie sur Bitcoin.': '時価総額上位百銘柄のうち、三十日間でビットコインを上回った割合です。75 % を超えると市場はアルトコインに傾き、25 % を下回るとビットコインへ回帰します。',
