  'D’où vient chaque chiffre, à quelle fréquence il est relevé, et ce que nous n’affichons pas faute de source.': 'それぞれの数字がどこから来て、どの頻度で取得され、出典がないために何を表示していないか。',
  'Les notions de marché expliquées, pour lire les pages sans dictionnaire.': '辞書なしでページを読めるように、市場の用語を解説します。',
