  '{n} des {u} premières capitalisations ont fait mieux que Bitcoin sur {d} jours.': '上位 {u} 銘柄のうち {n} 銘柄が {d} 日間でビットコインを上回りました。',
  'Comptage brut sur les {n} premières capitalisations, hors Bitcoin lui-même et hors stablecoins — dont la variation ne mesure rien d’autre que l’écart à leur ancrage. Ce n’est pas un signal d’achat ni de vente : voir [ce que ZENKUU ne fait pas](/aide/pas-de-conseil).': '上位 {n} 銘柄を対象とした単純な集計です。ビットコイン自身と、変動がペッグからの乖離しか表さないステーブルコインは除いています。売買のシグナルではありません。[ZENKUU が行わないこと](/aide/pas-de-conseil)をご覧ください。',

