  /* ── Fiche d’actif — explications et mentions ─────────────────────────────────────────── */
  'La pastille de couleur reprend le jugement de la source sur la crédibilité du volume annoncé — ce n’est pas un avis de ZENKUU. La profondeur ±2 % est le montant qu’il faudrait exécuter pour déplacer le cours de deux pour cent, à l’achat puis à la vente, en dollars.': '色付きの点は、公表された出来高の信頼性についてソース自身が下した判断を示すもので、ZENKUU の見解ではありません。±2 % の厚みとは、買いと売りのそれぞれで価格を 2 % 動かすのに必要な約定金額（ドル建て）です。',
  'ZENKUU n’exécute aucun ordre et ne détient aucun fonds. Ces liens mènent à des plateformes tierces, citées sans recommandation.': 'ZENKUU は注文を執行せず、資金も保有しません。これらのリンクは第三者のプラットフォームに繋がるもので、推奨を意味しません。',
  'Registre déclaratif : il recense ce que ces sociétés ont ANNONCÉ détenir, à la date de leur annonce. Ce n’est ni une mesure on-chain ni un état vérifié. Le coût total et la valeur du jour sont publiés en dollars ; leur écart est une plus ou moins-value latente, rien n’a été réalisé.': 'これは申告に基づく台帳です。各社が公表した時点で保有していると発表した数量を並べたもので、オンチェーンの計測でも監査済みの数値でもありません。取得総額と本日の評価額はドル建てで公表され、その差は含み損益にすぎず、売却は行われていません。',
  'Vote des visiteurs de la source, et non une mesure de marché : rien ne garantit qu’un vote corresponde à une position détenue.': 'これはソースの訪問者による投票であり、市場を測ったものではありません。投票が実際の保有ポジションに対応している保証はありません。',
  'Opinions de bureaux d’analyse, pas une prévision. Le consensus penche structurellement à l’achat : les recommandations de vente y sont rares.': 'これはアナリスト部門の見解であり、予測ではありません。コンセンサスは構造的に買いに傾いており、売り推奨はまれです。',
  'Un jeton adossé à une action n’EST pas cette action&nbsp;: il en réplique le cours par un mécanisme propre à son émetteur, avec ses propres risques de contrepartie et de liquidité. Les montants sont publiés en dollars par la source.': '株式に裏付けられたトークンは、その株式そのものではありません。発行体独自の仕組みで価格を追随させるもので、固有のカウンターパーティ・リスクと流動性リスクを伴います。金額はソースがドル建てで公表しています。',
  'Dernière valeur reçue pour chaque journée. La variation est calculée d’une journée à la précédente au sein de cette série.': '各日について受信した最後の値です。変化率は、この系列の中で前日と比較して算出しています。',
  'Carnet Binance · instantané, rafraîchi toutes les 5 s': 'Binance の板 · スナップショット、5秒ごとに更新',
  'Rotation du volume': '売買回転率',
