  'Le même jeton existe sur plusieurs chaînes, avec une adresse différente sur chacune. Vérifiez la chaîne avant toute opération : une adresse valide sur un réseau ne l’est sur aucun autre.': '同じトークンが複数のチェーン上に存在し、それぞれ異なるアドレスを持ちます。操作の前に必ずチェーンを確認してください。あるネットワークで有効なアドレスは、他のどのネットワークでも有効ではありません。',
