  'par paire et par période': 'ペア別・期間別',
  'Tendances du moment': 'いま注目',
  'Les actifs les plus consultés du moment, tous secteurs confondus. Une mesure d’ATTENTION, pas de performance : un actif peut être très regardé parce qu’il chute.': 'いま最も閲覧されている銘柄を、分野を問わず並べています。これは関心の大きさを測るものであり、成績ではありません。下落しているからこそ注目される銘柄もあります。',
  'La même période, comptée dans plusieurs unités. Une hausse en monnaie peut être une baisse en bitcoin : c’est ce que la première ligne ne dit pas et que les suivantes montrent.': '同じ期間を、複数の単位で数えたものです。法定通貨建てでの上昇が、ビットコイン建てでは下落ということもあります。最初の行が語らないことを、続く行が示します。',
  'La première ligne est publiée par la source. Les suivantes sont calculées en rapportant la variation de l’actif à celle du repère sur la même période — un rapport de rapports, non une soustraction. Une case vide signifie que l’une des deux variations n’est pas publiée.': '最初の行はソースが公表するものです。以降の行は、同じ期間における当該銘柄の変化率を基準の変化率で割って算出しています。引き算ではなく、比率どうしの比です。空欄は、二つの変化率のいずれかが公表されていないことを意味します。',
  'face à la finance traditionnelle': '伝統的金融との比較',
  'Performance de': 'パフォーマンス：',
  'La taille de cet actif, mise en face de valeurs dont l’ordre de grandeur est connu. La dernière colonne dit combien de fois il devrait grandir pour les égaler — au cours d’aujourd’hui.': 'この銘柄の規模を、桁数の見当がつく値と並べたものです。最終列は、本日の価格でそれらに並ぶには何倍になる必要があるかを示します。',
  'Les tailles de droite sont le cours du jour multiplié par une quantité déclarée — actions en circulation, stock extrait — dont la source et la date figurent dans le registre du site. Le multiple est un rapport de tailles ACTUEL : il ne prédit rien, ne fixe aucun objectif et ne constitue ni un conseil ni une recommandation.': '右側の規模は、本日の価格に、公表された数量（発行済株式数、採掘済在庫など）を掛けたものです。その出典と日付は当サイトの台帳に記載しています。倍率はあくまで現時点の規模の比であり、何かを予測するものでも、目標を示すものでも、助言や推奨でもありません。',
  '— la source ne publie les agrégats sectoriels que dans cette devise, et les convertir mêlerait deux horodatages.': '— ソースはセクター集計をこの通貨でしか公開しておらず、換算すると二つの時点が混ざってしまいます。',
  'Adresses de contrat de': 'コントラクトアドレス：',
